GROUPS = {1: [143, 131, 124], 2: [142, 144, 125]}
TAUS_US = [0, 1, 2, 3.4, 4, 8]


def tau_dt(dt):
    return {str(t): int(round(t * 1e-6 / dt / 2)) * 2 for t in TAUS_US}    # even, so tau/2 is whole


def build_B(backend):
    from qiskit import QuantumCircuit
    from qiskit.transpiler import generate_preset_pass_manager
    td = tau_dt(backend.dt)
    isa, rec = {}, {}
    for g, qs in GROUPS.items():
        for tau in TAUS_US:
            d = td[str(tau)]
            for v in ("R", "E"):
                qc = QuantumCircuit(3, 3, name=f"{v}{tau}-g{g}")
                for i in range(3):
                    qc.h(i)
                    if v == "R":
                        if d:
                            qc.delay(d, i, unit="dt")
                    else:
                        if d:
                            qc.delay(d // 2, i, unit="dt")
                        qc.x(i)
                        if d:
                            qc.delay(d // 2, i, unit="dt")
                    qc.h(i)
                    qc.measure(i, i)
                pm = generate_preset_pass_manager(backend=backend, optimization_level=0, initial_layout=qs, seed_transpiler=47)
                t = pm.run(qc)
                ops = {k: int(x) for k, x in t.count_ops().items()}
                init = list(t.layout.initial_index_layout(filter_ancillas=True))
                chk = {"layout": init == qs, "measures": ops.get("measure", 0) == 3, "no_2q": ops.get("cz", 0) == 0,
                       "x": ops.get("x", 0) == (3 if v == "E" else 0),
                       "delays": ops.get("delay", 0) == ((3 if v == "R" else 6) if d else 0)}
                isa[(g, tau, v)] = t
                rec[f"g{g}|{tau}|{v}"] = {"group": g, "qubits": qs, "tau_us": tau, "tau_dt": d, "variant": v, "count_ops": ops, "checks": chk}
    return isa, rec, td



def b_list():
    first = [(g, tau, v) for g in GROUPS for tau in TAUS_US for v in ("R", "E")]
    return [{"group": g, "tau_us": tau, "variant": v, "copy": 1} for g, tau, v in first] + \
           [{"group": g, "tau_us": tau, "variant": v, "copy": 2} for g, tau, v in first[::-1]]
